INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich mit Object-Storage direkt relationale Datenbanken ersetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Fehlt SQL-Unterstützung und Struktur"}, {"text": "Ja", "correct": false, "because": "Nur für unstrukturierte Daten geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für die Skalierbarkeit eines Speichersystems wie in der Cloud entscheidend?', 3, '[{"text": "Horizontale Skalierung", "correct": true, "because": "Ermöglicht unbegrenzte Kapazität"}, {"text": "Hohe Latenz", "correct": false, "because": "Verlangsamt Zugriff"}, {"text": "Feste Struktur", "correct": false, "because": "Einschränkt Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Speichersystem wie S3 besonders nützlich?', 5, '[{"text": "Metadatenverwaltung", "correct": true, "because": "Erleichtert Suche und Organisation"}, {"text": "Hohe Verfügbarkeit", "correct": true, "because": "Garantiert Zugriff"}, {"text": "Echtzeitverarbeitung", "correct": false, "because": "Nicht primär"}, {"text": "Festplattengröße", "correct": false, "because": "Cloud-abstrahiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Object-Storage nutzt flache Hierarchien. b) Es ist ideal für Echtzeit-Analysen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Ordnerstruktur, aber nicht für Echtzeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Speichersystems für unstrukturierte Daten?', 4, '[{"text": "Skalierbarkeit", "correct": false, "because": "Kern für große Datenmengen"}, {"text": "Zugriffszeit", "correct": false, "because": "Wichtig für Performance"}, {"text": "SQL-Kompatibilität", "correct": true, "because": "Nicht nötig für Objekte"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Metadaten in einem solchen Speicher immer erforderlich sind?', 2, '[{"text": "Nein", "correct": true, "because": "Optional für Organisation"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Läuft so ein Speicher direkt auf Blockebene?', 3, '[{"text": "Nein", "correct": true, "because": "Arbeitet mit Objekten, nicht Blöcken"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit Block-Storage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern den Zugriff auf gespeicherte Daten in der Cloud?', 5, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Datenintegrität"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Begrenzt unbefugten Zugriff"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nur für Geschwindigkeit"}, {"text": "Lokale Backups", "correct": false, "because": "Cloud-fremd"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Speicher immer teurer sind als lokale Festplatten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierung senkt Kosten langfristig"}, {"text": "Ja", "correct": false, "because": "Hängt von Nutzung ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Daten langfristig speichere?', 4, '[{"text": "Dauerhaftigkeit", "correct": true, "because": "Schützt vor Datenverlust"}, {"text": "Schnelle Schreibrate", "correct": false, "because": "Sekundär für Archivierung"}, {"text": "Geringe Kapazität", "correct": false, "because": "Widerspricht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Objekte haben eindeutige IDs. b) Sie unterstützen hierarchische Ordner.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flache Struktur, keine Ordner"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature finde ich bei einem Speicher für Medieninhalte entscheidend?', 4, '[{"text": "Skalierbare Kapazität", "correct": true, "because": "Bewältigt große Datenmengen"}, {"text": "Transaktionsunterstützung", "correct": false, "because": "Für Datenbanken relevant"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Speicher immer HTTP-basiert sind. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "RESTful APIs nutzen HTTP"}, {"text": "Nein", "correct": false, "because": "HTTP ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Zugriff auf gespeicherte Objekte?', 3, '[{"text": "API-Schlüssel", "correct": false, "because": "Für Authentifizierung nötig"}, {"text": "Eindeutige IDs", "correct": false, "because": "Identifizieren Objekte"}, {"text": "Lokale Installation", "correct": true, "because": "Cloud-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Speicher für transaktionale Daten geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Fehlt Konsistenzgarantie"}, {"text": "Ja", "correct": false, "because": "Für unstrukturierte Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein solches Speichersystem in der Cloud?', 5, '[{"text": "Globale Verfügbarkeit", "correct": true, "because": "Zugriff von überall"}, {"text": "Automatische Skalierung", "correct": true, "because": "Passt sich Bedarf an"}, {"text": "Echtzeit-Analysen", "correct": false, "because": "Nicht primär"}, {"text": "Feste Struktur", "correct": false, "because": "Flexibilität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Latenz bei solchen Speichern immer ein Problem?', 3, '[{"text": "Nein", "correct": true, "because": "Optimierte Netzwerke minimieren Latenz"}, {"text": "Ja", "correct": false, "because": "Hängt von Anbieter ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Wenn ich Daten in der Cloud speichere, was ist dann entscheidend?', 4, '[{"text": "Redundanz", "correct": true, "because": "Schützt vor Ausfällen"}, {"text": "Einzelne Festplatte", "correct": false, "because": "Nicht skalierbar"}, {"text": "Manuelle Backups", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Speicher immer öffentlich sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Private Buckets möglich"}, {"text": "Ja", "correct": false, "because": "Zugriffskontrollen vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem solchen Speicher?', 4, '[{"text": "Archivierung von Mediendaten", "correct": true, "because": "Skalierbar und kosteneffizient"}, {"text": "Echtzeit-Datenbank", "correct": false, "because": "Fehlt Konsistenz"}, {"text": "Lokale VM-Hosting", "correct": false, "because": "Andere Technologie"}]');
